describe('protected provenance API', () => {
  test('lists and inspects provenance for submitters', async () => {
    const provenance = service();
    const account = createTestAccount({ role: 'submitter' });

    await request(app(account, provenance))
      .get('/api/v1/provenance/submissions?limit=25')
      .set('Authorization', 'Bearer token')
      .expect(200);
    await request(app(account, provenance))
      .get('/api/v1/provenance/submissions/30')
      .set('Authorization', 'Bearer token')
      .expect(200);

    expect(provenance.listSubmissions).toHaveBeenCalledWith(account, { limit: 25 });
    expect(provenance.getSubmission).toHaveBeenCalledWith(account, '30');
  });

  test('blocks viewers before private provenance reaches the service', async () => {
    const provenance = service();
    const account = createTestAccount({ role: 'viewer' });

    await request(app(account, provenance))
      .get('/api/v1/provenance/events/101')
      .set('Authorization', 'Bearer token')
      .expect(403);

    expect(provenance.getEvent).not.toHaveBeenCalled();
  });

  test('routes event and statistic traces through authenticated services', async () => {
    const provenance = service();
    const account = createTestAccount({ role: 'admin', competitionIds: ['5'] });

    await request(app(account, provenance))
      .get('/api/v1/provenance/events/101')
      .set('Authorization', 'Bearer token')
      .expect(200);
    await request(app(account, provenance))
      .get('/api/v1/provenance/fixtures/7/statistics/stat_example')
      .set('Authorization', 'Bearer token')
      .expect(200);

    expect(provenance.getEvent).toHaveBeenCalledWith(account, '101');
    expect(provenance.getStatistic).toHaveBeenCalledWith(account, '7', 'stat_example');
  });
});

/**
 * One grouped row of a participant's derived figures.
 *
 * The repository returns the season, competition and career levels from a
 * single grouped statement, so a row carries flags saying which columns were
 * part of its grouping set rather than which level it belongs to.
 */
export interface ParticipantAggregateRow {
  /** True when this row groups by competition; false when it spans them all. */
  competitionGrouped: boolean;
  /** True when this row groups by season; false when it spans them all. */
  seasonGrouped: boolean;
  competitionId: string | null;
  competitionName: string | null;
  season: string | null;
  fixtureCount: number;
  sourceEventCount: number;
  /**
   * Deliveries in this group where the participant was the striker, including
   * wides. Zero means they never batted, which is what distinguishes an absent
   * batting record from a real score of nought.
   */
  battingDeliveryCount: number;
  runsScored: number;
  ballsFaced: number;
  fours: number;
  sixes: number;
  /** Deliveries in this group where the participant was the bowler. */
  bowlingDeliveryCount: number;
  runsConceded: number;
  /** Bowler-attributable wide runs, including multi-run wides and byes or leg byes run off a wide. */
  wides: number;
  /** Bowler-attributable no-ball runs, including the no-ball penalty. */
  noBalls: number;
  legalBallsBowled: number;
  wicketsTaken: number;
  /**
   * The balls-per-over of the fixtures in this group, or null where they do not
   * agree. Overs bowled and economy rate need a divisor and
   * `sport-domain-definition.md` Â§10 forbids assuming six, so a group spanning
   * different values reports neither.
   */
  ballsPerOver: number | null;
}

export interface ParticipantAggregatesSource {
  participantId: string;
  participantName: string;
  rows: ParticipantAggregateRow[];
}
import type {
  ParticipantAggregate,
  ParticipantAggregates,
  ParticipantAggregatesQuery,
} from '@sport-analytics/contracts';

import { createSeasonId } from '../public-read/season-id';
import { deriveParticipantAggregates } from './participant-aggregates.derivation';
import type { ParticipantAggregatesSource } from './participant-aggregates.model';
import { loadParticipantAggregatesSource } from './participant-aggregates.repository';

export type LoadParticipantAggregatesSource = (
  participantId: string,
) => Promise<ParticipantAggregatesSource | null>;

export interface ParticipantAggregatesService {
  getParticipantAggregates(
    participantId: string,
    query: ParticipantAggregatesQuery,
  ): Promise<ParticipantAggregates | null>;
  getParticipantAggregate(
    participantId: string,
    statisticId: string,
  ): Promise<ParticipantAggregate | null>;
}

const databaseIdPattern = /^\d+$/;

export function createParticipantAggregatesService(
  loadSource: LoadParticipantAggregatesSource = loadParticipantAggregatesSource,
): ParticipantAggregatesService {
  async function derive(
    participantId: string,
    query: ParticipantAggregatesQuery,
  ): Promise<ParticipantAggregates | null> {
    if (!databaseIdPattern.test(participantId)) {
      return null;
    }

    const source = await loadSource(participantId);
    if (!source) {
      return null;
    }

    return deriveParticipantAggregates(source, {
      ...(query.scope !== undefined ? { scope: query.scope } : {}),
      createSeasonId,
    });
  }

  return {
    getParticipantAggregates: derive,

    async getParticipantAggregate(participantId, statisticId) {
      // Resolved from the unfiltered derivation: a client holding a season
